-- Imports the 10 programs from the NXT LVL launchpad admin export (2026-10-07)
-- into the hub catalog (Program.type = suite_app, owned by the 'nxt-lvl' organization).
-- Insert-only: existing rows are never modified. If a slug is already taken in that organization,
-- the program is imported as '<slug>-suite' instead (so no program is lost) and a WARNING is logged.
-- Re-running is a no-op because rows are keyed by their deterministic ids. Generated by
-- scripts/generate-launchpad-import-migration.py from prisma/data/launchpad-programs-export-2026-10-07.json.
DO $$
DECLARE
  org_id TEXT;
  entry RECORD;
  target_slug TEXT;
BEGIN
  SELECT "id" INTO org_id FROM "Organization" WHERE "slug" = 'nxt-lvl' ORDER BY "createdAt" LIMIT 1;
  IF org_id IS NULL THEN
    RAISE WARNING 'suite catalog import skipped: organization nxt-lvl not found';
    RETURN;
  END IF;

  FOR entry IN
    SELECT * FROM (VALUES
    ('suite-timeflow', 'TimeFlow', 'timeflow', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "#dfeb2d", "adminOnly": false, "category": "Productivity", "displayOrder": 1, "externalUrl": "https://timeflow.nltops.com/", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "Time Management Program for entrepreneurs", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "Time Management Program for entrepreneurs", "status": "live", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "T", "id": "fcc9ba1f-c204-4bb0-b034-d91753053c5c", "pricingType": "", "published": true, "supportUrl": "", "tagline": "Time Management Program for entrepreneurs "}}'::jsonb),
    ('suite-fbapp', 'FBApp', 'fbapp', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "#000000", "adminOnly": false, "category": "Productivity", "displayOrder": 100, "externalUrl": "https://blacknbiz.com/", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "Your resource for black business nationwide!", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "Your resource for black business nationwide!", "status": "live", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "F", "id": "fd165bc6-8b97-4357-9850-0d7aa482f7c7", "pricingType": "", "published": true, "supportUrl": "", "tagline": "Your resource for black business nationwide!"}}'::jsonb),
    ('suite-nxt-lvl-music-studio', 'Nxt Lvl Music Studio', 'nxt-lvl-music-studio', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "#f59e0b", "adminOnly": false, "category": "Productivity", "displayOrder": 100, "externalUrl": "https://studio.nxtlvlts.com/", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "Music recording studio", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "Music recording studio", "status": "beta", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "N", "id": "93c0f1fc-ced3-42cf-a0fb-12e1c46e39db", "pricingType": "", "published": true, "supportUrl": "", "tagline": "Music recording studio"}}'::jsonb),
    ('suite-mejay', 'MeJay', 'mejay', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "#37012b", "adminOnly": false, "category": "Productivity", "displayOrder": 100, "externalUrl": "https://mejayapp.com/", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "", "status": "live", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "N", "id": "3e82b2ee-24b0-4336-80d7-bd31fc04308e", "pricingType": "", "published": true, "supportUrl": "", "tagline": ""}}'::jsonb),
    ('suite-card-list-capture', 'Card List Capture', 'card-list-capture', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "#22c55e", "adminOnly": false, "category": "Productivity", "displayOrder": 100, "externalUrl": "https://card-list-capture.pages.dev/", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "Convert photos of businees cards and sign up lists to downloable formats usable in excel and sheets", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "Convert photos of businees cards and sign up lists to downloable formats usable in excel and sheets", "status": "live", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "N", "id": "b4f7f0cd-9c88-4ed3-87aa-4a9ae4dbdd29", "pricingType": "", "published": true, "supportUrl": "", "tagline": "Convert photos of businees cards and sign up lists to downloable formats usable in excel and sheets"}}'::jsonb),
    ('suite-nxt-lvl-movie-maker', 'Nxt Lvl Movie Maker', 'nxt-lvl-movie-maker', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "#ec4899", "adminOnly": false, "category": "Productivity", "displayOrder": 100, "externalUrl": "https://cinema-studio-suite.pages.dev/", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "Movie maker with multi cam recording along with live camera switch recording", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "Movie maker with multi cam recording along with live camera switch recording", "status": "beta", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "N", "id": "1b69f7fa-109e-42d1-b7a4-26148810525d", "pricingType": "", "published": true, "supportUrl": "", "tagline": "Movie maker with multi cam recording along with live camera switch recording"}}'::jsonb),
    ('suite-mejay-v2', 'Mejay V2', 'mejay-v2', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "oklch(0.78 0.16 195)", "adminOnly": false, "category": "Productivity", "displayOrder": 100, "externalUrl": "https://mejay2.pages.dev/", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "", "status": "beta", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "N", "id": "efadddd1-f1a2-4b2d-a885-8c71a8aafd9c", "pricingType": "", "published": true, "supportUrl": "", "tagline": ""}}'::jsonb),
    ('suite-streamline', 'Streamline', 'streamline', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "#f59e0b", "adminOnly": false, "category": "Productivity", "displayOrder": 100, "externalUrl": "https://streamline.nxtlvlts.com/", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "", "status": "coming-soon", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "N", "id": "f16e5057-d4c5-4ea1-b637-d12835e4bdc0", "pricingType": "Free - subscription", "published": true, "supportUrl": "", "tagline": ""}}'::jsonb),
    ('suite-ticket-time', 'Ticket Time', 'ticket-time', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "#ec4899", "adminOnly": false, "category": "Productivity", "displayOrder": 100, "externalUrl": "https://tickettime.nltops.com", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "", "status": "coming-soon", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "N", "id": "682a36b4-c54c-49a9-a48a-4aff3416a582", "pricingType": "", "published": true, "supportUrl": "", "tagline": ""}}'::jsonb),
    ('suite-app-ally', 'Application Ally', 'app-ally', 'active'::"ProgramStatus", '{"catalog": {"accentColor": "#0ea5e9", "adminOnly": false, "category": "Productivity", "displayOrder": 100, "externalUrl": "https://appally.nltops.com/", "isFeatured": false, "isPublic": true, "launchLabel": "Launch Program", "logoUrl": "", "longDescription": "", "notes": "Imported from the NXT LVL launchpad admin export (2026-10-07).", "openInNewTab": true, "origin": "suite-native", "requiresApproval": false, "requiresLogin": false, "screenshotUrl": "", "secondaryCategory": "", "shortDescription": "", "status": "beta", "tags": [], "type": "external"}, "launchpad": {"accessType": "PUBLIC", "audiences": [], "benefits": [], "faqs": [], "features": [], "iconLetter": "A", "id": "56a22ff1-e015-413a-8e01-7d9740d7a9d4", "pricingType": "", "published": true, "supportUrl": "", "tagline": ""}}'::jsonb)
    ) AS v("id", "name", "slug", "status", "settings")
  LOOP
    CONTINUE WHEN EXISTS (SELECT 1 FROM "Program" WHERE "id" = entry."id");
    target_slug := entry."slug";
    IF EXISTS (SELECT 1 FROM "Program" WHERE "organizationId" = org_id AND "slug" = target_slug) THEN
      target_slug := entry."slug" || '-suite';
      RAISE WARNING 'suite catalog import: slug % already used in nxt-lvl, imported as %', entry."slug", target_slug;
    END IF;
    INSERT INTO "Program" ("id", "organizationId", "name", "slug", "type", "status", "settings", "createdAt", "updatedAt")
    VALUES (entry."id", org_id, entry."name", target_slug, 'suite_app', entry."status", entry."settings", CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
    ON CONFLICT DO NOTHING;
  END LOOP;
END $$;
